#!/usr/bin/env python3
"""Writes the hedra command files of the canyon's simple models (from art/assets.md, no sheet). The camera stands
behind the start platform (x -15) looking along +X across the gorge, so faces towards +X are never seen.
cliffs, river, mesas, post, rope, flag, streak, splash, bird, cactus, rock, sun.
Positions below are given in the scene's glTF frame (Y up, +Z towards the camera's side) and written
as hedra's (x, -z, y). The rope runs along X at y = 1.0 from x = -6.8 to 6.8; the canyon runs along
Z between the cliff walls at x = +-6.6, its river 6.5 m below the rim.
Run from this folder: python3 make_env.py; then `hedra model --text <m>.rmdl run <m>.txt` (build.sh)."""
import math

COL = {  # Dreamscape8, sRGB 0..1
    "C": "0.788 0.800 0.631", "O": "0.792 0.627 0.353", "R": "0.682 0.416 0.278", "B": "0.545 0.251 0.286",
    "U": "0.329 0.200 0.267", "S": "0.318 0.322 0.384", "G": "0.388 0.471 0.490", "A": "0.557 0.627 0.569"}

def mats(L, *pairs):
    for name, col in pairs:
        L.append(f"material new {name} --base-color {COL[col]} --no-slot")

def box(L, name, c, s, mat, rot=0.0, cull=False):
    """A box centred at glTF point c with sizes s (x, y up, z); rot turns it about the vertical."""
    L.append(f"add mesh cube --name {name} --size 1 --location {c[0]:.3f} {-c[2]:.3f} {c[1]:.3f}")
    L.append(f"scale {s[0]:.3f} {s[2]:.3f} {s[1]:.3f}")
    L.append("apply --scale")
    if rot:
        L.append(f"set rotation 0 0 {rot:.2f}")
    L.append(f"material assign {mat}")
    if cull:
        # faces the camera never sees: towards +X (away from it), the ends along the canyon, the bottom
        L += [f"active {name}", "mode edit",
              "select face where \"normal.x > 0.5 || abs(normal.y) > 0.5 || normal.z < -0.5\"",
              "delete face", "mode object"]

def write(name, L):
    L += ["select all", "shade flat", f"export {name}.glb"]
    open(f"{name}.txt", "w").write("\n".join(L) + "\n")

# --- cliffs: on each side three strata stepping in and out (sand on top, rust, red-brown), from the
# rim (y 0) down to below the river (y -6.9), 52 m along the canyon
L = ["# The canyon's two cliffs (generated by make_env.py).", "new"]
mats(L, ("Sand", "O"), ("Rust", "R"), ("Brick", "B"), ("Plateau", "O"))
layers = [(0.0, -1.2, "Sand", 0.0), (-1.2, -3.8, "Rust", -0.35), (-3.8, -6.9, "Brick", 0.25)]
for side, sx in (("Far", -1), ("Near", 1)):
    for k, (top, bot, mat, inset) in enumerate(layers):
        inner = 6.6 - inset
        outer = 11.0 if sx < 0 else (14.0 if k == 0 else 11.0)
        zr = 8.0 if sx < 0 else 24.0     # the near rim is seen only close to the rope; the far wall wide
        cx = sx * (inner + outer) / 2
        box(L, f"{side}{k}", (cx, (top + bot) / 2, 0.0), (outer - inner, top - bot, 2 * zr), mat, cull=True)
        if k > 0:  # a lower stratum's top is under the one above, but for its ledge
            L += [f"active {side}{k}", "mode edit", "select face where \"normal.z > 0.5\"", "delete face", "mode object"]
# the far plateau beyond the rim, out to the horizon (its own material: baked coarser)
box(L, "Plateau", (24.0, -0.6, 0.0), (20.0, 1.2, 48.0), "Plateau", cull=True)
# boulders fallen against the far wall's foot
for k, (x, y, z, r) in enumerate(((6.3, -6.3, -5, 0.8), (6.5, -6.4, 7, 1.0), (6.2, -6.3, -11, 0.6), (5.9, -6.4, 2.5, 0.5))):
    L.append(f"add mesh ico-sphere --name Boulder{k} --subdivisions 1 --radius {r} --location {x} {-z} {y}")
    L.append("material assign Rust")
write("cliffs", L)

# --- river: the canyon floor, a strip of water between two sand banks
L = ["# The river and its banks (generated by make_env.py), y = -6.6.", "new"]
mats(L, ("Water", "G"), ("Bank", "O"))
L.append(f"add mesh plane --name River --size 1 --location 0 0 -6.6")
L.append("scale 9.6 30 1")
L.append("apply --scale")
L.append("material assign Water")
for s in (-1, 1):
    L.append(f"add mesh plane --name Bank{'LR'[s > 0]} --size 1 --location {s * 5.2:.2f} 0 -6.55")
    L.append("scale 2.0 30 1")
    L.append("apply --scale")
    L.append("material assign Bank")
write("river", L)

# --- mesas on the far plateau's horizon (cool, fogged)
L = ["# Distant mesas (generated by make_env.py).", "new"]
mats(L, ("Far", "G"))
for k, (x, z, w, h, d) in enumerate(((40, -14, 8, 6.0, 7), (44, 3, 9, 8.0, 8), (38, 15, 6, 4.5, 6), (47, -4, 6, 3.5, 5))):
    box(L, f"Mesa{k}", (x, h / 2, z), (w, h, d), "Far", cull=True)
    L += [f"active Mesa{k}", "mode edit", "select face where \"normal.z > 0.5\"", "scale 0.82 0.82 1", "mode object"]
write("mesas", L)

# --- stand: the walker's platform at each end of the rope, 1.1 x 1.1 m, its deck 0.9 m up, two posts
# 1.4 m tall at the rope end (+X; the far stand is turned 180), the rope tied between them
L = ["# A rope stand (generated by make_env.py), origin at the deck's rope-end centre, on the ground.", "new"]
mats(L, ("Wood", "B"), ("Deck", "O"), ("Cap", "R"))
box(L, "Deck", (-0.55, 0.85, 0), (1.1, 0.1, 1.1), "Deck")
for k, (x, z) in enumerate(((-1.0, -0.45), (-1.0, 0.45), (-0.1, -0.45), (-0.1, 0.45))):
    box(L, f"Leg{k}", (x, 0.4, z), (0.12, 0.8, 0.12), "Wood")
for s_ in (-1, 1):
    box(L, f"Post{'LR'[s_ > 0]}", (0.0, 0.7, s_ * 0.42), (0.16, 1.4, 0.16), "Wood")
    box(L, f"Cap{'LR'[s_ > 0]}", (0.0, 1.44, s_ * 0.42), (0.24, 0.1, 0.24), "Cap")
box(L, "Bar", (0.0, 0.9, 0), (0.12, 0.12, 0.96), "Wood")
write("stand", L)

# --- rope: one 14 m length along +X from its origin (the game scales it down to each span)
L = ["# A rope segment (generated by make_env.py): 14 m along +X from the origin, 0.08 m thick.", "new"]
mats(L, ("Rope", "O"))
box(L, "Rope", (7.0, 0, 0), (14.0, 0.08, 0.08), "Rope")
write("rope", L)

# --- flag: a pennant on a short staff, flying towards +Z (the game turns it with the wind)
L = ["# A pennant (generated by make_env.py), origin at the staff's foot.", "new"]
mats(L, ("Staff", "U"), ("Cloth", "B"))
box(L, "Staff", (0, 0.45, 0), (0.06, 0.9, 0.06), "Staff")
L.append("add mesh cone --name Pennant --vertices 3 --radius1 0.32 --radius2 0 --depth 0.06 --location 0 -0.38 0.78 --rotation 90 0 0")
L.append("scale 0.55 1.25 1")
L.append("apply --scale")
L.append("material assign Cloth")
write("flag", L)

# --- streak: a wind streak, 1.6 m long along Z (unlit, cream)
L = ["# A wind streak (generated by make_env.py).", "new"]
mats(L, ("Wind", "C"))
box(L, "Streak", (0, 0, 0), (0.06, 0.06, 1.6), "Wind")
write("streak", L)

# --- splash: a crown of water drops
L = ["# A splash (generated by make_env.py), origin at the water.", "new"]
mats(L, ("Spray", "C"))
for k in range(6):
    a = math.radians(60 * k)
    L.append(f"add mesh ico-sphere --name Drop{k} --subdivisions 1 --radius 0.16 --location {0.45 * math.cos(a):.3f} {0.45 * math.sin(a):.3f} {0.35 + 0.15 * (k % 2)}")
    L.append("material assign Spray")
L.append("add mesh cone --name Column --vertices 6 --radius1 0.35 --radius2 0.12 --depth 0.9 --location 0 0 0.45")
L.append("material assign Spray")
write("splash", L)

# --- bird: a soaring hawk, 1.4 m wingspan, flying towards +Z
L = ["# A hawk (generated by make_env.py), origin at its body.", "new"]
mats(L, ("Feather", "U"), ("Belly", "B"))
box(L, "Body", (0, 0, 0), (0.18, 0.14, 0.6), "Belly")
for s in (-1, 1):
    box(L, f"Wing{'LR'[s > 0]}", (s * 0.4, 0.06, -0.02), (0.65, 0.05, 0.3), "Feather", rot=0)
    L.append(f"set rotation 0 {-12 * s} 0")
box(L, "Tail", (0, 0, -0.38), (0.24, 0.04, 0.2), "Feather")
write("bird", L)

# --- cactus: a saguaro with two arms
L = ["# A saguaro (generated by make_env.py), 2 m.", "new"]
mats(L, ("Cactus", "A"))
L.append("add mesh cylinder --name Trunk --vertices 6 --radius 0.18 --depth 2.0 --location 0 0 1.0")
L.append("material assign Cactus")
for s, h in ((-1, 0.9), (1, 1.2)):
    L.append(f"add mesh cylinder --name Arm{'LR'[s > 0]}0 --vertices 6 --radius 0.12 --depth 0.4 --location {s * 0.3} 0 {h} --rotation 0 90 0")
    L.append("material assign Cactus")
    L.append(f"add mesh cylinder --name Arm{'LR'[s > 0]}1 --vertices 6 --radius 0.12 --depth 0.6 --location {s * 0.46} 0 {h + 0.25}")
    L.append("material assign Cactus")
write("cactus", L)

# --- rock: a jittered icosahedron
L = ["# A rock (generated by make_env.py).", "new", "add mesh ico-sphere --name Rock --subdivisions 1 --radius 0.5 --location 0 0 0.25",
     "scale 1.3 1.0 0.7", "apply --scale", "mode edit", "select all", "randomize --amount 0.08 --seed 5", "mode object"]
mats(L, ("Stone", "R"))
L.append("material assign Stone")
write("rock", L)

# --- sun: a low evening sun, a flat 12-gon facing the camera (unlit)
L = ["# The sun (generated by make_env.py): a disc facing -X (the camera), 6 m across.", "new"]
mats(L, ("Sun", "C"))
L.append("add mesh cylinder --name Sun --vertices 12 --radius 3.0 --depth 0.1 --location 0 0 0 --rotation 0 90 0")
L.append("material assign Sun")
write("sun", L)
print("wrote cliffs river mesas stand rope flag streak splash bird cactus rock sun .txt")
